#!/bin/sh
# Started by SlotServe: sets up the logins, then runs the SSH server (Dropbear).
S=/opt/slotserve
. $S/lib.sh
setup() {
  if ! /bin/sh $S/accounts.sh; then
    echo "slotserve: could not create the user accounts, see above" >&2
    return 1
  fi
}
case "$1" in
  --setup) setup; exit $? ;;
  --run) ;;
  *) setup || exit 1 ;;
esac
exec $S/dropbearmulti dropbear -F -e -w -s -K 60 -T 3 -p 22 \
  -r $S/ssh_host_key -P /tmp/.slotserve-dropbear.pid
